using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
namespace UnturnedModManager {
 public static class VersionOrder {
  static readonly Regex numeric=new Regex(@"^(\d+(?:\.\d+){1,3})(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$");
  public static bool Valid(string value){return !string.IsNullOrWhiteSpace(value)&&value.Length<=80&&!value.Any(char.IsControl);}
  public static bool Comparable(string value){return value!=null&&numeric.IsMatch(value)&&numeric.Match(value).Groups[1].Value.Split('.').All(p=>{long n;return long.TryParse(p,out n);});}
  public static int? Compare(string a,string b){if(string.Equals(a,b,StringComparison.Ordinal))return 0;if(!Comparable(a)||!Comparable(b))return null;var x=numeric.Match(a);var y=numeric.Match(b);var ax=x.Groups[1].Value.Split('.').Select(long.Parse).ToArray();var by=y.Groups[1].Value.Split('.').Select(long.Parse).ToArray();for(int i=0;i<4;i++){long av=i<ax.Length?ax[i]:0,bv=i<by.Length?by[i]:0;if(av!=bv)return av.CompareTo(bv);}string ap=x.Groups[2].Value,bp=y.Groups[2].Value;if(ap.Length==0||bp.Length==0)return ap.Length==0?(bp.Length==0?0:1):-1;var aa=ap.Split('.');var bb=bp.Split('.');for(int i=0;i<Math.Min(aa.Length,bb.Length);i++){long an,bn;bool ai=long.TryParse(aa[i],out an),bi=long.TryParse(bb[i],out bn);int c=ai&&bi?an.CompareTo(bn):ai!=bi?(ai?-1:1):StringComparer.OrdinalIgnoreCase.Compare(aa[i],bb[i]);if(c!=0)return c;}return aa.Length.CompareTo(bb.Length);}
  public static bool Newer(string a,string b){return Compare(a,b)>0;}
  public static bool Test(string value){return value!=null&&(numeric.IsMatch(value)&&numeric.Match(value).Groups[2].Success||Regex.IsMatch(value,@"(?:^|[ ._-])(?:test|beta|alpha|preview|rc)\d*|測試|测试",RegexOptions.IgnoreCase));}
  public static IOrderedEnumerable<Package> Sort(IEnumerable<Package> packages,bool reliable){return reliable?packages.OrderByDescending(p=>p.Manifest.version,Comparer<string>.Create((a,b)=>Compare(a,b)??0)).ThenBy(p=>p.Folder,StringComparer.OrdinalIgnoreCase):packages.OrderBy(p=>p.ScanOrder).ThenBy(p=>p.Folder,StringComparer.OrdinalIgnoreCase);}
 }
 public class VersionDifference {
  public List<string> Added=new List<string>(),Removed=new List<string>(),Changed=new List<string>();
  public static VersionDifference Compare(Package a,Package b){if(a.Manifest.id!=b.Manifest.id)throw new Exception(L.Get("CompareHint"));var first=a.Manifest.files.ToDictionary(f=>f.target,f=>f.sha256,StringComparer.OrdinalIgnoreCase);var next=b.Manifest.files.ToDictionary(f=>f.target,f=>f.sha256,StringComparer.OrdinalIgnoreCase);return new VersionDifference{Added=next.Keys.Where(k=>!first.ContainsKey(k)).OrderBy(k=>k).ToList(),Removed=first.Keys.Where(k=>!next.ContainsKey(k)).OrderBy(k=>k).ToList(),Changed=next.Keys.Where(k=>first.ContainsKey(k)&&!Data.Same(first[k],next[k])).OrderBy(k=>k).ToList()};}
 }
 public class SourceDependency {public string relative;public string sha256;}
 public class PackageScope {public string id;public string label;}
 public static class WorkshopTargets {
  public static List<string> ContentRoots(string game,IEnumerable<string> libraries,string explicitRoot=null){var result=new List<string>();if(!string.IsNullOrWhiteSpace(game)){var common=System.IO.Directory.GetParent(System.IO.Path.GetFullPath(game).TrimEnd(System.IO.Path.DirectorySeparatorChar,System.IO.Path.AltDirectorySeparatorChar));if(common!=null&&common.Parent!=null&&string.Equals(common.Name,"common",StringComparison.OrdinalIgnoreCase)&&string.Equals(common.Parent.Name,"steamapps",StringComparison.OrdinalIgnoreCase))result.Add(System.IO.Path.Combine(common.Parent.FullName,"workshop","content","304930"));}if(!string.IsNullOrWhiteSpace(explicitRoot)&&explicitRoot.Replace('\\','/').TrimEnd('/').EndsWith("/steamapps/workshop/content/304930",StringComparison.OrdinalIgnoreCase))result.Add(System.IO.Path.GetFullPath(explicitRoot));if(libraries!=null)result.AddRange(libraries.Select(l=>System.IO.Path.Combine(l,"steamapps","workshop","content","304930")));return result.Distinct(StringComparer.OrdinalIgnoreCase).ToList();}
  public static string Resolve(string game,string scope,IEnumerable<string> roots){if(!Regex.IsMatch(scope??"",@"^\d{1,20}$"))throw new Exception(L.Get("ScopeInvalid"));var candidates=ContentRoots(game,null).Concat(roots??new string[0]).Distinct(StringComparer.OrdinalIgnoreCase).Select(r=>Paths.Safe(r,scope)).Where(System.IO.Directory.Exists).ToList();if(candidates.Count==0)throw new Exception(L.Get("ScopeMissing")+scope);var preferred=ContentRoots(game,null).Select(r=>Paths.Safe(r,scope)).FirstOrDefault(System.IO.Directory.Exists);if(preferred!=null)return preferred;if(candidates.Count!=1)throw new Exception(L.Get("ScopeAmbiguous")+scope);return candidates[0];}
  public static void VerifySources(Package p,string root){foreach(var f in p.Manifest.files){if(string.IsNullOrEmpty(f.source_sha256)){if(!string.IsNullOrEmpty(f.source_file)||f.source_dependencies!=null&&f.source_dependencies.Count>0)throw new Exception(L.Get("SourceChanged")+f.target);continue;}string original=f.source_file;if(string.IsNullOrEmpty(original))original=f.target.StartsWith("Localization/Tchinese/",StringComparison.Ordinal)?f.target.Replace("Localization/Tchinese/","Localization/English/"):f.target.Substring(0,f.target.LastIndexOf('/')+1)+"English.dat";VerifySource(root,f.target,original,f.source_sha256);if(f.source_dependencies!=null)foreach(var d in f.source_dependencies){if(d==null)throw new Exception(L.Get("SourceChanged"));VerifySource(root,f.target,d.relative,d.sha256);}}}
  static void VerifySource(string root,string target,string relative,string hash){string folder=target.Substring(0,target.LastIndexOf('/')+1);bool expected=target.StartsWith("Localization/Tchinese/",StringComparison.Ordinal)&&relative==target.Replace("Localization/Tchinese/","Localization/English/");bool sibling=relative!=null&&relative.StartsWith(folder,StringComparison.Ordinal)&&relative.Substring(folder.Length).IndexOf('/')<0&&(relative.EndsWith(".dat",StringComparison.OrdinalIgnoreCase)||relative.EndsWith(".asset",StringComparison.OrdinalIgnoreCase))&&!relative.EndsWith("Tchinese.dat",StringComparison.OrdinalIgnoreCase);if(!expected&&!sibling)throw new Exception(L.Get("ScopeInvalid")+relative);string source=Paths.Safe(root,relative);if(!Data.ValidHash(hash)||!System.IO.File.Exists(source)||!Data.Same(Data.Hash(source),hash))throw new Exception(L.Get("SourceChanged")+relative);}
 }
}
